<?php require_once '../includes/auth.php'; requireActiveUser(); requireTenantContext(); requireModulePermission('subscriptions','view'); $tid=getCurrentTenantId(); $rows=[]; if(flexihubTableHasColumn('internet_accounts','tenant_id')){ $q=$conn->prepare("SELECT * FROM internet_accounts WHERE tenant_id=? ORDER BY id DESC LIMIT 200"); if($q){$q->bind_param('i',$tid);$q->execute();$r=$q->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$q->close();}} $pageTitle='Subscriptions'; require_once '../includes/header.php'; require_once '../includes/sidebar.php'; ?><main class="main-content"><div class="page-header"><h1>Subscriptions</h1><p>Customer internet services and subscription status.</p></div><div class="card"><table class="table"><thead><tr><th>Account</th><th>Customer</th><th>Plan</th><th>Status</th><th>Expiry</th></tr></thead><tbody><?php foreach($rows as $x): ?><tr><?php $v=fn($k)=>e($x[$k]??''); ?><td><?= $v('account_number') ?: $v('username') ?></td><td><?= $v('customer_id') ?></td><td><?= $v('plan_id') ?></td><td><?= $v('status') ?></td><td><?= $v('expiry_date') ?: $v('expires_at') ?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="5">No subscriptions found.</td></tr><?php endif; ?></tbody></table></div></main><?php require_once '../includes/footer.php'; ?>